using System.Runtime.InteropServices;

namespace KOYA_APP
{
    public class WebZoomAction : IStreamDeckAction
    {
        public string Name => "Zoom WWW / Aplikacji";
        public string Icon => "";
        public string Description => "Przybliza/oddala (Ctrl + Scroll)";

        [DllImport("user32.dll")]
        private static extern void keybd_event(byte bVk, byte bScan, uint dwFlags, int dwExtraInfo);

        [DllImport("user32.dll")]
        private static extern void mouse_event(uint dwFlags, int dx, int dy, uint dwData, int dwExtraInfo);

        private const byte VK_CONTROL = 0x11;
        private const uint MOUSEEVENTF_WHEEL = 0x0800;
        private const uint KEYEVENTF_KEYUP = 0x0002;

        public void Execute() { /* Klikniecie moze resetowac zoom Ctrl+0 */ 
            keybd_event(VK_CONTROL, 0, 0, 0);
            keybd_event(0x30, 0, 0, 0); // '0'
            keybd_event(0x30, 0, KEYEVENTF_KEYUP, 0);
            keybd_event(VK_CONTROL, 0, KEYEVENTF_KEYUP, 0);
        }

        public void ExecuteAnalog(bool direction)
        {
            keybd_event(VK_CONTROL, 0, 0, 0);
            // 120 = jeden skok scrolla w gore, -120 = w dol
            uint data = direction ? (uint)120 : unchecked((uint)-120);
            mouse_event(MOUSEEVENTF_WHEEL, 0, 0, data, 0);
            keybd_event(VK_CONTROL, 0, KEYEVENTF_KEYUP, 0);
        }
    }
}

