using System.Windows;
using System.Windows.Input;
using System.Windows.Controls;

namespace KOYA_APP
{
    public partial class MainWindow : Window
    {
        private IStreamDeckAction[] _buttonActions = new IStreamDeckAction[14]; // 12 przyciskow + 2 potencjometry

        public MainWindow()
        {
            InitializeComponent();
        }

        private void OnDeckButtonClick(object sender, RoutedEventArgs e)
        {
            Button btn = (Button)sender;
            if (btn.Tag == null) return;

            if (!int.TryParse(btn.Tag.ToString(), out int index)) return;
            if (index < 0 || index >= _buttonActions.Length) return;

            if (_buttonActions[index] == null)
            {
                // Jesli to potencjometr (index 12 lub 13), mozemy pozniej dodac filtracje w pickerze
                ActionPicker picker = new ActionPicker { Owner = this };
                if (picker.ShowDialog() == true)
                {
                    _buttonActions[index] = picker.SelectedAction!;
                    btn.Content = _buttonActions[index].Icon;
                    btn.ToolTip = _buttonActions[index].Name;
                }
            }
            else
            {
                _buttonActions[index].Execute(); // Wykonaj klikniecie
            }
        }

        private void OnKnobMouseWheel(object sender, MouseWheelEventArgs e)
        {
            Button btn = (Button)sender;
            if (btn.Tag == null) return;
            if (!int.TryParse(btn.Tag.ToString(), out int index)) return;

            if (_buttonActions[index] != null)
            {
                // e.Delta > 0 oznacza ruch w prawo (do przodu)
                _buttonActions[index].ExecuteAnalog(e.Delta > 0);
            }
        }

        private void TitleBar_MouseDown(object sender, MouseButtonEventArgs e) { if (e.ChangedButton == MouseButton.Left) this.DragMove(); }
        private void Close_Click(object sender, RoutedEventArgs e) => Application.Current.Shutdown();       
        private void Minimize_Click(object sender, RoutedEventArgs e) => this.WindowState = WindowState.Minimized;

        // Stare metody do usuniecia/puste dla kompatybilnosci XAML
        private void VolumeUp_Click(object sender, RoutedEventArgs e) { }
        private void VolumeDown_Click(object sender, RoutedEventArgs e) { }
    }
}

