using NAudio.CoreAudioApi;

namespace KOYA_APP
{
    public class MuteMicrophoneAction : IStreamDeckAction
    {
        public string Name => "Mute Mikrofon";
        public string Icon => "\uE1D6";
        public string Description => "Wycisza mikrofon";

        public void Execute()
        {
            try
            {
                var enumerator = new MMDeviceEnumerator();
                var device = enumerator.GetDefaultAudioEndpoint(DataFlow.Capture, Role.Communications);
                device.AudioEndpointVolume.Mute = !device.AudioEndpointVolume.Mute;
            }
            catch { }
        }

        public void ExecuteAnalog(bool direction)
        {
            try
            {
                var enumerator = new MMDeviceEnumerator();
                var device = enumerator.GetDefaultAudioEndpoint(DataFlow.Capture, Role.Communications);
                float step = 0.02f;
                float current = device.AudioEndpointVolume.MasterVolumeLevelScalar;
                device.AudioEndpointVolume.MasterVolumeLevelScalar = direction ? 
                    System.Math.Min(1.0f, current + step) : 
                    System.Math.Max(0.0f, current - step);
            }
            catch { }
        }
    }
}

